package com.yeyamo_mobile.api.notification_service.application;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import com.yeyamo_mobile.api.notification_service.application.port.*;import com.yeyamo_mobile.api.notification_service.domain.*;
class DeliveryServiceTest{@Test void marksSuccessfulDeliverySent(){var deliveries=mock(DeliveryRepositoryPort.class);var notifications=mock(NotificationRepositoryPort.class);var sender=mock(ChannelSender.class);when(sender.channel()).thenReturn(NotificationChannel.EMAIL);Delivery d=delivery();Notification n=notification(d.notificationId());when(deliveries.findDue(any(),eq(10))).thenReturn(List.of(d));when(notifications.findById(d.notificationId())).thenReturn(Optional.of(n));new DeliveryService(deliveries,notifications,List.of(sender),5,30).dispatch(10);verify(sender).send(d,n);ArgumentCaptor<Delivery>captor=ArgumentCaptor.forClass(Delivery.class);verify(deliveries).save(captor.capture());assertEquals(DeliveryStatus.SENT,captor.getValue().status());}@Test void schedulesRetryWhenSenderFails(){var deliveries=mock(DeliveryRepositoryPort.class);var notifications=mock(NotificationRepositoryPort.class);var sender=mock(ChannelSender.class);when(sender.channel()).thenReturn(NotificationChannel.EMAIL);doThrow(new IllegalStateException("SMTP down")).when(sender).send(any(Delivery.class),any(Notification.class));Delivery d=delivery();when(deliveries.findDue(any(),eq(10))).thenReturn(List.of(d));when(notifications.findById(d.notificationId())).thenReturn(Optional.of(notification(d.notificationId())));new DeliveryService(deliveries,notifications,List.of(sender),5,30).dispatch(10);ArgumentCaptor<Delivery>captor=ArgumentCaptor.forClass(Delivery.class);verify(deliveries).save(captor.capture());assertEquals(DeliveryStatus.RETRY,captor.getValue().status());}private Delivery delivery(){return new Delivery(UUID.randomUUID(),UUID.randomUUID(),NotificationChannel.EMAIL,"u@test.io",DeliveryStatus.PENDING,0,Instant.now(),null,null);}private Notification notification(UUID id){return new Notification(id,UUID.randomUUID(),"user.created","u1","Title","Body","{}",Instant.now(),null);}}
